        INPUT["输入 Token 流"] --> LOOKAHEAD["前看符号"]
        LOOKAHEAD --> TABLE["查解析表"]
        TABLE --> SHIFT["移进: 压栈 + 前进"]
        TABLE --> REDUCE["归约: 弹栈 + 构建节点"]
